   const fechaVisibleAIso=valor=>{const partes=String(valor||'').trim().split('/');return partes.length===3&&partes.every(Boolean)?`${partes[2]}-${partes[1].padStart(2,'0')}-${partes[0].padStart(2,'0')}`:String(valor||'').trim()};
