    const renderCalendario=()=>{const año=mes.getFullYear();const mesNumero=mes.getMonth();const primerDia=(new Date(año,mesNumero,1).getDay()+6)%7;const cantidadDias=new Date(año,mesNumero+1,0).getDate();calendario.innerHTML='<div class="purchase-calendar-head"><button type="button" data-prev aria-label="Mes anterior">‹</button><strong>'+nombreMeses[mesNumero]+' '+año+'</strong><button type="button" data-next aria-label="Mes siguiente">›</button></div><div class="purchase-calendar-week">'+diasSemana.map(dia=>'<span>'+dia+'</span>').join('')+'</div><div class="purchase-calendar-days">'+Array.from({length:primerDia},()=>'<span></span>').join('')+Array.from({length:cantidadDias},(_,indice)=>{const dia=indice+1;const iso=año+'-'+String(mesNumero+1).padStart(2,'0')+'-'+String(dia).padStart(2,'0');return '<button type="button" data-date="'+iso+'">'+dia+'</button>'}).join('')+'</div>';calendario.querySelector('[data-prev]').onclick=()=>{mes=new Date(año,mesNumero-1,1);renderCalendario()};calendario.querySelector('[data-next]').onclick=()=>{mes=new Date(año,mesNumero+1,1);renderCalendario()};calendario.querySelectorAll('[data-date]').forEach(boton=>boton.onclick=()=>{const partes=boton.dataset.date.split('-');input.value=partes[2]+'/'+partes[1]+'/'+partes[0];calendario.hidden=true;input.dispatchEvent(new Event('input',{bubbles:true}))})};
